    return jdbc.query("SELECT t.release_id, r.from_version, r.to_version"
                    + " FROM rollout_task t JOIN release_order r ON r.id = t.release_id"
                    + " WHERE t.device_id = ? AND t.status = 'SUCCESS'"
                    + " ORDER BY t.id",
