private List<HopSpec> buildPath(Device device, String targetVersion) {
    List<VersionEdge> edges = taskRepository.findSuccessEdgesByDevice(device.deviceId());
    // 历史代次一致：相邻边必须首尾相接
    for (int i = 1; i < edges.size(); i++) {
        if (!edges.get(i).fromVersion().equals(edges.get(i-1).toVersion())) {
            throw conflict GENERATION_MISMATCH;
        }
    }
    // 当前版本一致：最后一条成功边的目标版本必须等于设备当前版本
    String current = device.currentVersion();
    if (!edges.isEmpty() && !edges.get(edges.size()-1).toVersion().equals(current)) {
        throw conflict CURRENT_VERSION_MISMATCH;
    }
    List<HopSpec> hops = new ArrayList<>();
    String cursor = current;
    int i = edges.size() - 1;
    while (!cursor.equals(targetVersion)) {
        if (i < 0) throw conflict NO_PATH;
        if (hops.size() >= 5) throw conflict PATH_TOO_LONG;
        VersionEdge edge = edges.get(i);
        // cursor == edge.toVersion by continuity
        hops.add(new HopSpec(edge.toVersion(), edge.fromVersion(), edge.releaseId()));
        cursor = edge.fromVersion();
        i--;
    }
    if (hops.isEmpty()) throw conflict NO_PATH_SAME_VERSION; // current == target
    return hops;
}
```

