public RollbackDispatchResponse dispatch(long planId, RollbackDispatchRequest request) {
    String fingerprint = join("rollback.dispatch", planId, deviceId);
    return idempotency.execute(request.requestId(), "rollback.dispatch", fingerprint, () -> {
        RollbackPlan plan = planRepository.findByIdForUpdate(planId)
            .orElseThrow(() -> notFound PLAN_NOT_FOUND);
        if (plan.status() == CANCELLED) throw conflict PLAN_CANCELLED;
        if (plan.status() == COMPLETED) throw conflict PLAN_COMPLETED;
        if (plan.status() == PAUSED) throw conflict PLAN_PAUSED; // 尚未派发和后续跳停止
        RollbackPlanDevice member = planDeviceRepository.find(planId, deviceId)
            .orElseThrow(() -> notFound? or conflict DEVICE_NOT_IN_PLAN);
        deviceRepository.findByIdForUpdate(deviceId).orElseThrow(...); // lock device
        if (taskRepository.hasPendingByDevice(deviceId)) throw conflict DEVICE_BUSY_ROLLOUT;
        for (int hop = 1; hop <= member.hopCount(); hop++) {
            var latest = hopTaskRepository.findLatest(planId, deviceId, hop);
            if (latest.isPresent() && latest.get().status() == SUCCESS) continue;
            if (latest.isPresent() && latest.get().roundNo() == plan.monitorRound()) {
                return new RollbackDispatchResponse(RollbackHopTaskView.of(latest.get()));
            }
            // 新一轮或无任务：派发
            RollbackHop hopDef = hopRepository.find(planId, deviceId, hop).orElseThrow(...);
            String receiptKey = "rk" + UUID.randomUUID().toString().replace("-", "");
            try {
                long taskId = hopTaskRepository.insert(receiptKey, planId, deviceId, hop,
                    plan.monitorRound(), hopDef.expectedVersion(), hopDef.targetVersion(), hopDef.sourceReleaseId());
                return new RollbackDispatchResponse(RollbackHopTaskView.of(hopTaskRepository.findById(taskId).orElseThrow()));
            } catch (DuplicateKeyException e) {
                return new RollbackDispatchResponse(RollbackHopTaskView.of(
                    hopTaskRepository.findLatest(planId, deviceId, hop).orElseThrow()));
            }
        }
        return new RollbackDispatchResponse(null); // 全部跳已成功
    }, RollbackDispatchResponse.class);
}
