public RollbackHopTaskView receipt(long hopTaskId, RollbackReceiptRequest request) {
    String fingerprint = join("rollback.receipt", hopTaskId, receiptKey, result);
    return idempotency.execute(request.requestId(), "rollback.receipt", fingerprint, () -> {
        RollbackHopTask snapshot = hopTaskRepository.findById(hopTaskId)
            .orElseThrow(() -> notFound HOP_TASK_NOT_FOUND);
        if (!snapshot.receiptKey().equals(request.receiptKey())) {
            throw conflict RECEIPT_KEY_MISMATCH;
        }
        RollbackPlan lockedPlan = planRepository.findByIdForUpdate(snapshot.planId()).orElseThrow(...);
        RollbackHopTask task = hopTaskRepository.findByIdForUpdate(hopTaskId).orElseThrow(...);
        return switch (task.status()) {
            case PENDING -> {
                if (lockedPlan.status() == CANCELLED) throw conflict PLAN_CANCELLED; // 取消后不再接收新回执
                hopTaskRepository.complete(hopTaskId, result);
                planRepository.incrementRoundStats(plan.id(), result);
                if (result == SUCCESS) {
                    deviceRepository.updateCurrentVersion(task.deviceId(), task.targetVersion());
                }
                RollbackPlan updated = planRepository.findById(plan.id()).orElseThrow();
                pauseIfThresholdReached(updated, task);
                completeIfAllArrived(updated.id());
                yield RollbackHopTaskView.of(hopTaskRepository.findById(hopTaskId).orElseThrow());
            }
            case SUCCESS, FAILED -> same result → view; else 409 RECEIPT_RESULT_CONFLICT;
            case CANCELLED -> 409 TASK_CANCELLED;
        };
    }, RollbackHopTaskView.class);
}
