private void pauseIfThresholdReached(RollbackPlan plan, RollbackHopTask trigger) {
    if (plan.status() != ACTIVE) return;
    int success = hopTaskRepository.countByHopRoundAndResult(plan.id(), trigger.hopIndex(), plan.monitorRound(), SUCCESS);
    int failed = ... FAILED;
    int samples = success + failed;
    if (samples < plan.sampleFloor()) return;
    if ((long) failed * 100 < (long) samples * plan.failureThresholdPercent()) return;
    if (planRepository.pauseIfActive(plan.id(), trigger.hopIndex()) == 1) {
        pauseRecordRepository.insert(plan.id(), plan.monitorRound(), trigger.hopIndex(), trigger.id(), success, failed, Instant.now(clock).toString());
    }
}
