            completeRollout("ke" + round, "e" + round, model, "1.0.0", "2.0.0");
            long planId = rollbackService.create(new CreateRollbackPlanRequest(
                    "r-c" + round, "pk-" + round, rel, "1.0.0", List.of(deviceId, "e" + round), 2, 50))
                    .planId();
