    @BeforeEach
    void setUp() {
        jdbc.update("DELETE FROM rollback_plan_pause_record");
        jdbc.update("DELETE FROM rollback_hop_task");
        jdbc.update("DELETE FROM rollback_plan_hop");
        jdbc.update("DELETE FROM rollback_plan_device");
